CREATE TABLE `ourlink_db1`.`mus_compositions` ( `CompositionId` INT NOT NULL AUTO_INCREMENT , `CompositionName` VARCHAR(200) NOT NULL , `DisambiguatingDescription` VARCHAR(100) NULL DEFAULT NULL , `Slug` VARCHAR(50) NULL DEFAULT NULL , `InLanguage` VARCHAR(3) NULL DEFAULT NULL , `Country` VARCHAR(6) NULL DEFAULT NULL , `YearPublished` VARCHAR(4) NULL DEFAULT NULL , `ComposerText` VARCHAR(500) NULL DEFAULT NULL , `LyricistText` VARCHAR(500) NULL DEFAULT NULL , `Tags` VARCHAR(255) NULL DEFAULT NULL , `DerivedFromCompositionId` INT NULL DEFAULT NULL , `Lyrics` TEXT NULL DEFAULT NULL , `ChordProSpec` TEXT NULL DEFAULT NULL , `LilyPondSpec` TEXT NULL DEFAULT NULL , `MusicalKey` VARCHAR(10) NULL DEFAULT NULL , `AlternateKey` VARCHAR(10) NULL DEFAULT NULL , `AlternateKeyLabel` VARCHAR(50) NULL DEFAULT NULL , `CopyrightInfo` VARCHAR(1000) NULL DEFAULT NULL , `CopyrightContactEmail` VARCHAR(255) NULL DEFAULT NULL , `Url1` VARCHAR(1000) NULL DEFAULT NULL , `Url1Label` VARCHAR(50) NULL DEFAULT NULL , `Url2` VARCHAR(1000) NULL DEFAULT NULL , `Url2Label` VARCHAR(50) NULL DEFAULT NULL , `Url3` VARCHAR(1000) NULL DEFAULT NULL , `Url3Label` VARCHAR(50) NULL DEFAULT NULL , `UpdatedOn` DATETIME NULL DEFAULT NULL , `UpdatedBy` INT NULL DEFAULT NULL , `CreatedOn` DATETIME NULL DEFAULT NULL , `CreatedBy` INT NULL DEFAULT NULL , PRIMARY KEY (`CompositionId`)) ENGINE = InnoDB CHARSET=utf8 COLLATE utf8_general_ci;
